import{_ as t,o as e,c as d,ag as c}from"./chunks/framework.BaNuf0sO.js";const h=JSON.parse('{"title":"flow-run 运行态族","description":"","frontmatter":{},"headers":[],"relativePath":"docs/flow/src/components/flow-run/README.md","filePath":"docs/flow/src/components/flow-run/README.md"}'),n={name:"docs/flow/src/components/flow-run/README.md"};function r(s,o,a,l,u,p){return e(),d("div",null,[...o[0]||(o[0]=[c('<h1 id="flow-run-运行态族" tabindex="-1">flow-run 运行态族 <a class="header-anchor" href="#flow-run-运行态族" aria-label="Permalink to &quot;flow-run 运行态族&quot;">​</a></h1><p><strong>只读运行轨迹展示</strong>——与 <code>flow</code> 编排族（可编辑画布）互补：编排族回答「流程长什么样」，本族回答「这次跑了哪些步、每步的进料与输出是什么」。</p><p>🔴 <strong>本族刻意不基于画布引擎</strong>：只读轨迹通常 ≤10 节点，拖 <code>@antv/x6</code> 属大材小用，且轨迹的信息密度诉求是<strong>树 / 时间线</strong>而非自由布局画布。对标观测系 Trace View（LangSmith / Langfuse）。[MUST NOT] 用「让 <code>FlowEditor</code> 支持只读模式」替代本族。</p><table tabindex="0"><thead><tr><th>组件</th><th>职责</th><th>文档</th></tr></thead><tbody><tr><td><code>FlowRunSteps</code></td><td>执行步骤树（顺序步 + 并行支 fanout + 条件分支组 + 失败详情 + 时间轴档）</td><td><a href="/done-coding-showcase/docs/flow/src/components/flow-run/docs/README-FlowRunSteps.html">README-FlowRunSteps.md</a></td></tr><tr><td><code>FlowRunIo</code></td><td>单步进料参数 / 输出 + 反馈区（三格只读壳）</td><td><a href="/done-coding-showcase/docs/flow/src/components/flow-run/docs/README-FlowRunIo.html">README-FlowRunIo.md</a></td></tr><tr><td><code>FlowRunBox</code></td><td>二合一集大成件：左树右 IO，选中步自动按 <code>io</code> 表取进料/输出；<code>#input</code> / <code>#output</code> / <code>#feedback</code> 插槽透传（<code>#feedback</code> 的 scope 额外带 <code>step</code>）</td><td><a href="/done-coding-showcase/docs/flow/src/components/flow-run/docs/README-FlowRunBox.html">README-FlowRunBox.md</a></td></tr></tbody></table><p>类型（<code>types.ts</code> 真相源）：<code>FlowRunStepStatusEnum</code> / <code>FlowRunStepStatus</code> / <code>FlowRunStepNode</code> / <code>FlowRunStepError</code> / <code>FlowRunStepsProps</code> / <code>FlowRunIoProps</code> / <code>FlowRunStepIo</code> / <code>FlowRunBoxProps</code>。</p><p>内部件：<code>RunStepList.vue</code>（递归渲染一串步骤 + 并行分支组，经 provide 取根上下文）、<code>utils.ts</code>（纯函数：时长格式化 / 取值降级归一）——均不出桶，消费方不直接使用。</p><h2 id="两条贯穿全族的纪律" tabindex="-1">两条贯穿全族的纪律 <a class="header-anchor" href="#两条贯穿全族的纪律" aria-label="Permalink to &quot;两条贯穿全族的纪律&quot;">​</a></h2><p><strong>Ⓐ 只画不判断。</strong> 组件不推断「哪步在跑」「哪步该算超时」——<code>running</code> 时调用方传「已执行 + 当前」，终态传全量。推断必然和服务端真相打架，而打架时<strong>页面看起来一切正常</strong>。</p><p><strong>Ⓑ 诚实缺省。</strong> 取不回的东西显示「没取到」，[MUST NOT] 拿默认值 / 现行版本冒充历史值。全族统一判据：</p><table tabindex="0"><thead><tr><th>值</th><th>语义</th><th>渲染</th></tr></thead><tbody><tr><td><code>undefined</code></td><td><strong>没取到</strong></td><td>缺省说明文案</td></tr><tr><td><code>null</code> / <code>&quot;&quot;</code> / <code>[]</code> / <code>{}</code></td><td>取到了，但是空值</td><td>空值本身</td></tr></tbody></table><p>同理 <code>durationMs</code> 无值 = 没量到 ⇒ 不显示，[MUST NOT] 显示成 <code>0ms</code>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><ul><li><strong>纯展示，数据 in / 事件 out</strong>：不提供数据获取、不焊后端、不焊模型。</li><li><strong>不按业务 schema 分型渲染</strong>：分型是应用层语义。包侧只给插槽（<code>#input</code> / <code>#output</code>），应用层自己处理——无论那头是 agent 提示词回放、还是别的什么。</li></ul>',13)])])}const w=t(n,[["render",r]]);export{h as __pageData,w as default};
